class Solution:
    def minFinishTime(self, n, edges, baseTime):
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        ans = float('inf')
        for root in range(n):
            par = [-1] * n
            seen = [False] * n
            seen[root] = True
            order, st = [], [root]
            while st:
                v = st.pop()
                order.append(v)
                for w in adj[v]:
                    if not seen[w]:
                        seen[w] = True
                        par[w] = v
                        st.append(w)
            F = [0] * n
            for v in reversed(order):
                fs = [F[w] for w in adj[v] if w != par[v]]
                F[v] = baseTime[v] if not fs else 2 * max(fs) - min(fs) + baseTime[v]
            ans = min(ans, F[root])
        return ans

