        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        par = [-1] * n
        seen = [False] * n
        seen[0] = True
        order, st = [], [0]
        while st:
            v = st.pop()
            order.append(v)
            for w in adj[v]:
                if not seen[w]:
                    seen[w] = True
                    par[w] = v
                    st.append(w)
        NEG, POS = float('-inf'), float('inf')
        F = [0] * n
        mx1 = [NEG] * n; mx2 = [NEG] * n
        mn1 = [POS] * n; mn2 = [POS] * n
        wm = [-1] * n; wn = [-1] * n
        for v in reversed(order):
            for w in adj[v]:
                if par[w] == v:
                    f = F[w]
                    if f > mx1[v]:
                        mx2[v] = mx1[v]; mx1[v] = f; wm[v] = w
                    elif f > mx2[v]:
                        mx2[v] = f
                    if f < mn1[v]:
                        mn2[v] = mn1[v]; mn1[v] = f; wn[v] = w
                    elif f < mn2[v]:
                        mn2[v] = f
